// App component using the generic event-loop scheduler
export function App(scheduler: Scheduler) {
  const [routeCode, setRouteCode] = useState("");
  const [cycleCode, setCycleCode] = useState("");
  const [rows, setRows] = useState<ReadSummary[]>([]);
  const [count, setCount] = useState<number | null>(null);
  const [selected, setSelected] = useState<Read | null>(null);
  const [flagging, setFlagging] = useState(false);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const describe = (err: unknown): string =>
    err instanceof Error ? `${err.name}: ${err.message}` : "the operation could not be completed";

  const runSearch = async () => {
    setLoading(true);
    setError(null);
    setSelected(null);
    setFlagging(false);
